#include "freedreno_perfcntr.h"

#define REG8(_x) REG_A8XX_##_x

#define FD8_COUNTER(_sel, _offset) COUNTER_BASE(_sel, _offset+0, _offset+1)
#define FD8_COUNTABLE(_sel) COUNTABLE_BASE(#_sel, A7XX_##_sel, UINT64, AVERAGE)

/* FIXME: this is a limited listing of perfcntr counter groups on a8xx,
 * only specifying the CP group counter registers and countable values
 * which are used by the new autotuner implementation. The perfcntr data
 * will also be autogenerated in the near future, so adding complete a8xx
 * support should be done under that effort.
 *
 * CP counter registers have changed on a8xx, but we can reuse the a7xx
 * countable list since we don't have the a8xx-specific list yet, and the
 * autotuner is only interested in countables that should be common between
 * a7xx and a8xx.
 */

